// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the from address, the callee address (but we'll deploy a helper to ensure CALL succeeds),
    // an array length and values
    function testFuzz_property(address from, uint8 len, uint256 seed) public {
        // keep len reasonable but allow 0 to be excluded by require in C
        uint256 _len = bound(len, 1, 10); // ensure non-empty as required by contract

        // build arrays
        address[] memory tos = new address[](_len);
        uint256[] memory vals = new uint256[](_len);

        // deploy a benign helper that always returns successfully to simulate a contract callee
        CalleeHelper helper = new CalleeHelper();

        for (uint i = 0; i < _len; i++) {
            // create deterministic but varying addresses by deploying small helpers
            // deploy distinct CalleeHelper instances so addresses vary with seed
            CalleeHelper h = new CalleeHelper();
            tos[i] = address(h);
            // pseudo-randomize values from seed
            vals[i] = uint256(keccak256(abi.encodePacked(seed, i)));
        }

        // Now call transfer and capture whether it returns true (without revert)
        bool ok;
        try c.transfer(from, address(helper), tos, vals) returns (bool ret) {
            ok = ret;
        } catch {
            ok = false; // if it reverts, treat as false
        }

        // The universal property: reference C always returns true (ok == true) for any non-empty tos array.
        // The mutant that returns false will cause this assertion to fail for some inputs.
        assertTrue(ok);
    }
}

// Minimal benign callee: accepts calls and returns without reverting.
contract CalleeHelper {
    fallback() external payable {
        // do nothing, just accept the call
    }
}
